	requireMutationConfirmation(args);
	const input = await loadMutationInput(
		mutationData(args),
		updateBodyMeasurementDataSchema,
		readDataSource,
	);
	const date = parseMeasurementDate(args.positionals[0] ?? input.date);
	if (input.date !== date)
		throw new UsageError("Measurement date does not match --data.date");
	return {
		body_measurement: await updateMeasurement(
			operations,
			date,
			input,
			execution,
		),
	};
}

function executeMeasurements(context: CommandContext): CommandResult {
	switch (context.args.subcommand) {
		case "list":
			return executeMeasurementList(context);
		case "get":
			return executeMeasurementGet(context);
		case "create":
			return executeMeasurementCreate(context);
		case "update":
			return executeMeasurementUpdate(context);
		default:
			throw new UsageError("Unknown command; run hevy --help");
	}
}

async function executeFolderCreate({
	args,
	operations,
	readDataSource,
	execution,
}: CommandContext) {
	requireMutationConfirmation(args);
	const input = await loadMutationInput(
		mutationData(args),
		routineFolderInputSchema,
		readDataSource,
	);
	return {
		routine_folder: await runOperation(
			operations.folders?.create,
			"folders.create",
			input,
			execution,
		),
	};
}

async function executeSummary({
	args,
	operations,
	now,
	execution,
}: CommandContext) {
	const weeks = parseWeeks(args);
	const to = now();
	const from = new Date(to.getTime() - weeks * 7 * 24 * 60 * 60 * 1000);
	const result = await runOperation(
		operations.workflows?.trainingSummary,
		"workflows.trainingSummary",
		{ weeks },
		execution,
	);
	const totalVolumeKg =
		z
			.number()
			.safeParse(
				(result.workouts as { readonly total_volume_kg?: unknown })
					.total_volume_kg,
			).data ?? 0;
	return {
		weeks,
		start_date: from.toISOString(),
		end_date: to.toISOString(),
		workout_count: result.workouts.count,
		total_duration_seconds: result.workouts.total_duration_seconds,
		exercise_count: result.workouts.exercise_count,
		set_count: result.workouts.set_count,
		total_volume_kg: totalVolumeKg,
		pages_scanned: result.workflow.pagination.workouts,
		complete: true,
	};
}

export async function execute(
	args: CliArgs,
	client: HevyClient,
	now = () => new Date(),
	readDataSource: DataSourceReader = defaultDataSourceReader,
	operations: HevyOperations = createOperations(client, {
		trainingSummaryMaxWeeks: 520,
		trainingSummaryStrictPagination: true,
	}),
	execution?: HevyExecutionOptions,
): Promise<unknown> {
	const context: CommandContext = {
		args,
		client,
		now,
		readDataSource,
		operations,
		execution,
	};
	if (args.command === "user" && !args.subcommand)
		return {
			user: {
				data: await runOperationWithoutInput(
					operations.user?.get,
					"user.get",
					context.execution,
				),
			},
		};
	if (args.command === "workouts") return executeWorkouts(context);
	if (args.command === "routines") return executeRoutines(context);
	if (args.command === "exercises") return executeExercises(context);
	if (args.command === "measurements") return executeMeasurements(context);
	if (args.command === "folders" && args.subcommand === "create")
		return executeFolderCreate(context);
	if (args.command === "summary") return executeSummary(context);
	throw new UsageError("Unknown command; run hevy --help");
}

import { createExecutionErrorProjection } from "@hevy-mcp/core";
import {
	ApiError,
	HevyHttpError,
	isHevyHttpError,
	NetworkError,
	NotFoundError,
	RateLimitError,
	ValidationError,
} from "@hevy-mcp/hevy-client";
import {
	EmptyMeasurementUpdateError,
	PaginationMismatchError,
	TrainingSummaryDataError,
	TrainingSummaryValidationError,
	WorkoutPayloadError,
	WorkoutPrivacyError,
} from "@hevy-mcp/operations";
import { ConfigurationError, UsageError } from "./arguments.js";

export class ApiResponseError extends Error {}

export const EXIT = { configuration: 1, usage: 2, api: 3, network: 4 } as const;

export interface CliDiagnostic {
	code: number;
	message: string;
	outcome?: string;
	phase?: string;
	operation_safety?: string;
	commit_state?: string;
	safe_to_retry?: boolean;
}

type TaggedClientError =
	| ApiError
	| NetworkError
	| NotFoundError
	| RateLimitError
	| ValidationError;

type OperationDomainError =
	| EmptyMeasurementUpdateError
	| PaginationMismatchError
	| TrainingSummaryDataError
	| TrainingSummaryValidationError
	| WorkoutPayloadError
	| WorkoutPrivacyError;

function isTaggedClientError(
	error: Error | string,
): error is TaggedClientError {
	return (
		error instanceof ApiError ||
		error instanceof NetworkError ||
		error instanceof NotFoundError ||
		error instanceof RateLimitError ||
		error instanceof ValidationError
	);
}

function isOperationDomainError(
	error: Error | string,
): error is OperationDomainError {
	return (
		error instanceof EmptyMeasurementUpdateError ||
		error instanceof TrainingSummaryDataError ||
		error instanceof PaginationMismatchError ||
		error instanceof TrainingSummaryValidationError ||
		error instanceof WorkoutPayloadError ||
		error instanceof WorkoutPrivacyError
	);
}

function executionFields(
	error: Error | string,
): Omit<CliDiagnostic, "code" | "message"> {
	if (!isHevyHttpError(error) && !isTaggedClientError(error)) return {};
	const {
		code: _code,
		status: _status,
		...execution
	} = createExecutionErrorProjection(error);
	return execution;
}

export function diagnostic(error: Error | string): CliDiagnostic {
	if (error instanceof ConfigurationError)
		return { code: EXIT.configuration, message: error.message };
	if (error instanceof ApiResponseError)
		return {
			code: EXIT.api,
			message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
			...executionFields(error),
		};
	if (isOperationDomainError(error)) {
		if (
			error instanceof PaginationMismatchError ||
			error instanceof WorkoutPayloadError ||
			error instanceof TrainingSummaryDataError
		) {
			return {
				code: EXIT.api,
				message:
					error instanceof PaginationMismatchError
						? "The API returned invalid pagination metadata"
						: error.message,
			};
		}
		return { code: EXIT.usage, message: error.message };
	}
	if (
		error instanceof HevyHttpError ||
		isHevyHttpError(error) ||
		isTaggedClientError(error)
	) {
		const status = "status" in error ? error.status : undefined;
		if (status === 401)
			return {
				code: EXIT.api,
				message: "Authentication failed; check HEVY_API_KEY",
				...executionFields(error),
			};
		if (status !== undefined)
			return {
				code: EXIT.api,
				message: `Hevy API request failed (HTTP ${status})`,
				...executionFields(error),
			};
		return {
			code: EXIT.network,
			message:
				("code" in error ? error.code : undefined) === "ETIMEDOUT"
					? "Hevy API request timed out"
					: "Unable to reach the Hevy API",
			...executionFields(error),
		};
	}
	if (error instanceof UsageError)
		return {
			code: EXIT.usage,
			message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
		};
	return { code: EXIT.usage, message: "Command failed" };
}

import {
	createHevyClient,
	type HevyClient,
	type HevyExecutionOptions,
} from "@hevy-mcp/hevy-client";
import { bindClientExecution, type ToolExecutionContext } from "@hevy-mcp/core";
import { createOperations, type HevyOperations } from "@hevy-mcp/operations";
import { getApiKey } from "./auth.js";
import { diagnostic, EXIT } from "./errors.js";
import { readDataSource, type DataSourceReader } from "./input.js";
import { runRoutes, type CliState } from "./routes.js";
import { writeResult, type Streams } from "./output/write.js";
export interface RunCliOptions {
	argv: string[];
	env?: Record<string, string | undefined>;
	clientFactory?: (key: string) => HevyClient;
	now?: () => Date;
	readDataSource?: DataSourceReader;
	streams?: Streams;
	execution?: ToolExecutionContext;
}

export async function runCli(options: RunCliOptions): Promise<number> {
	const streams = options.streams ?? {
		stdout: (text) => process.stdout.write(text),
		stderr: (text) => process.stderr.write(text),
	};
	const state: CliState = {};
	const stricliProcess = {
		stdout: { write: streams.stdout },
		stderr: { write: streams.stderr },
		exitCode: undefined as number | undefined,
	};
	const context = {
		process: stricliProcess,
		state,
		now: options.now ?? (() => new Date()),
		readDataSource: options.readDataSource ?? readDataSource,
		client: undefined as HevyClient | undefined,
		operations: undefined as HevyOperations | undefined,
		execution: options.execution as HevyExecutionOptions | undefined,
	};
	const metaCommand = options.argv.some((value) =>
		["--help", "-h", "--version", "-v"].includes(value),
	);
	try {
		if (!metaCommand) {
			const key = getApiKey(options.env ?? globalThis.process.env);
			const createdClient = (
				options.clientFactory ?? ((apiKey) => createHevyClient({ apiKey }))
			)(key);
			const client = options.execution
				? bindClientExecution(createdClient, options.execution)
				: createdClient;
			context.client = client;
			context.operations = createOperations(createdClient, {
				trainingSummaryMaxWeeks: 520,
				trainingSummaryStrictPagination: true,
			});
		}
		const exitCode = await runRoutes(options.argv, context);
		if (state.error !== undefined) throw state.error;
		if (exitCode !== 0) return EXIT.usage;
		if (state.result !== undefined) {
			const json = options.argv.includes("--json");
			writeResult(state.result, json, streams);
		}
		return 0;
	} catch (error) {
		const normalizedError = error instanceof Error ? error : String(error);
		const failure = diagnostic(normalizedError);
		if (options.argv.includes("--json")) {
			streams.stderr(`${JSON.stringify(failure)}\n`);
		} else {
			streams.stderr(`${failure.message}\n`);
		}
		return failure.code;
	}
}

